N = 50  # golfers
G = 5   # group size
W = 7   # weeks
K = 10  # groups per week

# Let's try a constructive approach first
# We'll use a greedy algorithm to build the schedule

def greedy_schedule():
    # Track which pairs have been used
    used_pairs = set()
    schedule = [[-1] * N for _ in range(W)]

    for w in range(W):
        # Assign golfers to groups for this week
        groups = [[] for _ in range(K)]
        golfers = list(range(N))

        # For each group, try to fill it
        for g in range(K):
            for _ in range(G):
                # Find a golfer who can join this group
                best_golfer = None
                for p in golfers:
                    # Check if p can join group g (no pair conflicts)
                    can_join = True
                    for existing in groups[g]:
                        pair = (min(p, existing), max(p, existing))
                        if pair in used_pairs:
                            can_join = False
                            break
                    if can_join:
                        best_golfer = p
                        break

                if best_golfer is not None:
                    groups[g].append(best_golfer)
                    golfers.remove(best_golfer)
                else:
                    # Need to backtrack or try different ordering
                    return None

        # Record pairs for this week
        for g in range(K):
            for i in range(G):
                for j in range(i+1, G):
                    pair = (min(groups[g][i], groups[g][j]), max(groups[g][i], groups[g][j]))
                    used_pairs.add(pair)

        # Assign group numbers
        for g in range(K):
            for p in groups[g]:
                schedule[w][p] = g

    return schedule

result = greedy_schedule()
