import random

N = 50
G = 5
W = 7
K = 10

def solve_social_golfers():
    # We'll build the schedule week by week
    # For each week, we need to partition N golfers into K groups of G

    # Track used pairs
    used_pairs = set()

    # Schedule: schedule[w][p] = group of golfer p in week w
    schedule = [[-1] * N for _ in range(W)]

    def can_assign(week, golfer, group, current_group_members):
        """Check if golfer can be assigned to group in this week"""
        for existing in current_group_members:
            pair = (min(golfer, existing), max(golfer, existing))
            if pair in used_pairs:
                return False
        return True

    def assign_week(week, group_idx, group_members):
        """Try to fill groups for a given week"""
        if group_idx == K:
            # All groups filled for this week
            for g in range(K):
                for p in group_members[g]:
                    schedule[week][p] = g
            return True

        # Determine which golfers are already assigned
        assigned = set()
        for g in range(group_idx):
            for p in group_members[g]:
                assigned.add(p)

        unassigned = [p for p in range(N) if p not in assigned]

        if len(unassigned) < G:
            return False

        # Try to fill this group
        # Use a recursive approach with backtracking
        def fill_group(remaining, current_members):
            if len(current_members) == G:
                # Group is full, move to next group
                group_members[group_idx] = current_members
                # Add pairs to used_pairs
                for i in range(G):
                    for j in range(i+1, G):
                        pair = (min(current_members[i], current_members[j]), 
                                max(current_members[i], current_members[j]))
                        used_pairs.add(pair)

                if assign_week(week, group_idx + 1, group_members):
                    return True

                # Backtrack
                for i in range(G):
                    for j in range(i+1, G):
                        pair = (min(current_members[i], current_members[j]), 
                                max(current_members[i], current_members[j]))
                        used_pairs.discard(pair)
                return False

            if not remaining:
                return False

            # Try each remaining golfer
            for i, p in enumerate(remaining):
                if can_assign(week, p, group_idx, current_members):
                    new_remaining = remaining[:i] + remaining[i+1:]
                    if fill_group(new_remaining, current_members + [p]):
                        return True

            return False

        return fill_group(unassigned, [])

    for w in range(W):
        print(f"Working on week {w}...")
        group_members = [[] for _ in range(K)]
        if not assign_week(w, 0, group_members):
            print(f"Failed at week {w}")
            return None
        print(f"  Week {w} completed")

    return schedule

# Try with a smarter ordering
